import { CSSProperties, Fragment, memo, useMemo } from 'react';
import { getTextFromChildren, takeStringOutOfNodeAndChildren } from '@/utils/text';
import { openExternal } from '@/utils/ui';
import ReactMarkdown, { Components } from 'react-markdown';
import {
  Blockquote,
  Group,
  ScrollArea,
  Text,
  ThemeIcon,
  Tooltip,
  Stack,
  Anchor,
  Pill,
  Typography,
} from '@mantine/core';
import RemarkGfm from 'remark-gfm';
import RemarkBreaks from 'remark-breaks';
import { CodeHighlight } from '@mantine/code-highlight';
import katex from 'katex';
import 'katex/dist/katex.min.css';
import { Icon } from '@iconify/react';
import { normalizeText } from '@tiny-chat/core-backend/src/types.ts';
import { visit, SKIP } from 'unist-util-visit';
import type { Plugin } from 'unified';
import type { Root, Element, Text as HastText } from 'hast';
import { SearchResult } from '@tiny-chat/core-backend/src/providers/search';

const rehypeStreamFade: Plugin<[], Root> = () => {
  return (tree) => {
    let totalLength = 0;
    visit(tree, 'text', (node: HastText) => {
      totalLength += node.value.length;
    });

    if (totalLength === 0) return;

    const animateChars = 15;
    const startIndex = Math.max(0, totalLength - animateChars);

    let currentIndex = 0;

    visit(tree, 'text', (node: HastText, index, parent) => {
      if (!parent || typeof index !== 'number') return;

      const nodeStart = currentIndex;
      const nodeLength = node.value.length;
      const nodeEnd = nodeStart + nodeLength;
      currentIndex += nodeLength;

      if (nodeEnd <= startIndex) return;

      const staticLength = Math.max(0, startIndex - nodeStart);
      const staticStr = node.value.slice(0, staticLength);
      const animatedStr = node.value.slice(staticLength);

      const newNodes: (HastText | Element)[] = [];
      if (staticStr) {
        newNodes.push({ type: 'text', value: staticStr });
      }

      for (let i = 0; i < animatedStr.length; i++) {
        const char = animatedStr[i];
        if (char.trim() === '') {
          const last = newNodes[newNodes.length - 1];
          if (last?.type === 'text') {
            last.value += char;
          } else {
            newNodes.push({ type: 'text', value: char });
          }
          continue;
        }

        const globalCharIndex = nodeStart + staticLength + i;
        newNodes.push({
          type: 'element',
          tagName: 'span',
          properties: {
            className: ['stream-char-fade'],
            key: `char-fade-${globalCharIndex}`,
          },
          children: [{ type: 'text', value: char }],
        });
      }

      parent.children.splice(index, 1, ...newNodes);
      return [SKIP, index + newNodes.length];
    });
  };
};

const STREAMING_MARKER = '\uE000';
const MATH_MARKER = '\uE001';
const CODE_MARKER = '\uE002';
const WRITING_MARKER = '\uE003';

const renderKatex = (math: string, displayMode: boolean): string | null => {
  try {
    return katex.renderToString(math, {
      displayMode,
      throwOnError: false,
      output: 'html',
    });
  } catch {
    return null;
  }
};

const components = (webSearchResults: SearchResult[] = []): Components => ({
  blockquote: (node) => {
    const text = getTextFromChildren(node.children);

    if (text.trim().startsWith(WRITING_MARKER)) {
      return (
        <Blockquote
          icon={
            <ThemeIcon variant="transparent" color="dimmed">
              <Icon icon="lucide:pencil-line" height={18} />
            </ThemeIcon>
          }
        >
          {takeStringOutOfNodeAndChildren(node.children, WRITING_MARKER)}
        </Blockquote>
      );
    }

    if (text.trim().startsWith('::>:: ')) {
      const lines = text.split('\n');
      let modelName = '';
      let contentLines = lines;

      const firstContent = lines[0].replace(/^::>::\s?/, '');
      if (firstContent.startsWith('::model=') && firstContent.endsWith('::')) {
        modelName = firstContent.slice('::model='.length, -2);
        contentLines = lines.slice(1);
      }

      return (
        <>
          {modelName && (
            <Group gap={5} c="dimmed" mb={4}>
              <Icon
                icon="lucide:message-square-quote"
                height={14}
                style={{ transform: 'scale(-1,1)' }}
              />
              <Text size="xs">{modelName}</Text>
            </Group>
          )}
          <Blockquote className="ignore-typography" mb="var(--mantine-spacing-lg)">
            {contentLines.map((line, index) => (
              <Fragment key={index}>
                {line.replace(/^::>::\s?/gm, '')}
                {index < contentLines.length - 1 && <br />}
              </Fragment>
            ))}
          </Blockquote>
        </>
      );
    }

    return <Blockquote>{node.children}</Blockquote>;
  },
  a: (props) => {
    if (webSearchResults && (props as { ['data-footnote-ref']?: string })['data-footnote-ref']) {
      const footnoteId = props.href?.replace('#user-content-fn-', '') ?? '';
      const citation = webSearchResults.find((c) => c.id === footnoteId);
      if (!citation) {
        // Fallback to index if no ID match (for older messages or if model ignored instructions)
        const index = parseInt(footnoteId, 10);
        const fallbackCitation = webSearchResults[index - 1];
        if (!fallbackCitation) return <sup>{props.children}</sup>;
        return (
          <Tooltip
            label={
              <Stack gap="xs" maw={300}>
                <Text size="sm" fw={500} lineClamp={2}>
                  {fallbackCitation.title}
                </Text>
                <Anchor size="xs" href={fallbackCitation.source} target="_blank" lineClamp={1}>
                  {fallbackCitation.source}
                </Anchor>
              </Stack>
            }
            multiline
            color="dark"
            position="bottom"
            bg="var(--tc-surface)"
            bd="1px solid var(--mantine-color-default-border)"
            p="md"
          >
            <Pill
              size="xs"
              style={{
                cursor: 'pointer',
                fontSize: '0.7em',
                margin: '0 2px',
                display: 'inline-flex',
              }}
              onClick={(e) => {
                e.preventDefault();
                void openExternal(fallbackCitation.source);
              }}
            >
              {fallbackCitation.title.length > 20
                ? fallbackCitation.title.slice(0, 17) + '…'
                : fallbackCitation.title}
            </Pill>
          </Tooltip>
        );
      }

      return (
        <Tooltip
          label={
            <Stack gap="xs" maw={300}>
              <Text size="sm" fw={500} lineClamp={2}>
                {citation.title}
              </Text>
              <Anchor size="xs" href={citation.source} target="_blank" lineClamp={1}>
                {citation.source}
              </Anchor>
            </Stack>
          }
          multiline
          color="dark"
          position="bottom"
          bg="var(--tc-surface)"
          bd="1px solid var(--mantine-color-default-border)"
          p="md"
        >
          <Pill
            size="xs"
            style={{
              cursor: 'pointer',
              fontSize: '0.7em',
              margin: '0 2px',
              display: 'inline-flex',
            }}
            onClick={(e) => {
              e.preventDefault();
              void openExternal(citation.source);
            }}
          >
            {citation.title.length > 20 ? citation.title.slice(0, 17) + '…' : citation.title}
          </Pill>
        </Tooltip>
      );
    }
    return (
      <a
        href={props.href}
        onClick={(e) => {
          if (!props.href) return;
          e.preventDefault();
          void openExternal(props.href);
        }}
      >
        {props.children}
      </a>
    );
  },
  code: (node) => {
    // eslint-disable-next-line @typescript-eslint/no-base-to-string
    const rawCode = String(node.children ?? '');

    // Display math — converted from $$...$$ by filter()
    if (node.className === 'language-math') {
      const html = renderKatex(rawCode.trim(), true);
      if (html) return <span className="math-display" dangerouslySetInnerHTML={{ __html: html }} />;
      return <pre>{rawCode}</pre>;
    }

    // Inline math — converted from $...$ by filter()
    if (!node.className && rawCode.startsWith(MATH_MARKER)) {
      const math = rawCode.slice(MATH_MARKER.length);
      const html = renderKatex(math, false);
      if (html) return <span className="math-inline" dangerouslySetInnerHTML={{ __html: html }} />;
      return <code>{math}</code>;
    }

    const isStreaming = rawCode.includes(STREAMING_MARKER);
    const code = (isStreaming ? rawCode.replace(STREAMING_MARKER, '') : rawCode).trimEnd();

    if (!node.className) {
      return <code>{code}</code>;
    }

    if (isStreaming) {
      return <pre style={{ padding: 25, maxHeight: 180, overflow: 'hidden' }}>{code}</pre>;
    }

    return (
      <div className="code-fade-in">
        <CodeHighlight
          code={code}
          language={node.className?.replace('language-', '')}
          withExpandButton={code.split('\n').length >= 8}
          defaultExpanded={code.split('\n').length < 8}
        />
      </div>
    );
  },
  table: (node) => {
    return (
      <ScrollArea scrollbars="x" type="always">
        <table>{node.children}</table>
      </ScrollArea>
    );
  },
});

const LATEX_CHAR_RE = /[\\^_{}]|\\[a-zA-Z]/;

const filter = (text: string) => {
  text = normalizeText(text);

  text = text.replace(/((?:^::>:: .*$\n?)+)/gm, (block) =>
    block.replace(/^::>:: (.*)$/gm, '> ::>:: $1'),
  );

  // Convert :::writing ... ::: directive blocks into standard blockquotes with the writing marker
  text = text.replace(/^:::writing\s*\n([\s\S]*?)^:::\s*$/gm, (_, content: string) => {
    const lines = content.trimEnd().split('\n');
    return lines.map((l: string, i: number) => `> ${i === 0 ? WRITING_MARKER : ''}${l}`).join('\n');
  });

  const codeBlocks: string[] = [];
  text = text.replace(/(`{3,}[\s\S]*?`{3,}|``[^`\n]*``|`[^`\n]+`)/g, (match) => {
    codeBlocks.push(match);
    return `\x00${CODE_MARKER}${codeBlocks.length - 1}\x00`;
  });

  // Step 2: Display math — $$...$$
  // Block form: $$ alone on line → fenced math block
  text = text.replace(
    /^[ \t]*\$\$([\s\S]*?)\$\$[ \t]*$/gm,
    (_, inner: string) => '```math\n' + inner.trim() + '\n```',
  );
  // Inline form: $$ with trailing content on same line → inline math marker
  text = text.replace(
    /\$\$((?:[^$]|\$(?!\$))+?)\$\$/g,
    (_, inner: string) => '`' + MATH_MARKER + inner.trim() + '`',
  );

  // Step 3: Display math — \[...\] (block, possibly multiline)
  text = text.replace(
    /^[ \t]*\\\[([\s\S]*?)\\][ \t]*$/gm,
    (_, inner: string) => '```math\n' + inner.trim() + '\n```',
  );

  // Step 4: Inline math — \(...\)
  // Allow any content that isn't a newline; filter false positives via LATEX_CHAR_RE
  text = text.replace(/\\\(([^\n]*?)\\\)/g, (match, inner: string) => {
    if (!LATEX_CHAR_RE.test(inner)) return match;
    return '`' + MATH_MARKER + inner.trim() + '`';
  });

  text = text.replace(
    /(?<![\\$a-zA-Z\d])\$[ \t]?((?:[^$\\\n]|\\.)+?)[ \t]?\$(?!\$)/g,
    (match, inner: string) => {
      const trimmed = inner.trim();
      if (!trimmed) return match;

      // Reject digit content with no LaTeX chars (e.g. $20k, $500)
      if (/^\d[\d,.]*[a-zA-Z]+$/.test(trimmed)) return match;

      // Reject ${ template literals
      if (trimmed.startsWith('{')) return match;

      // Reject if content starts with a ticker-like pattern: 2–5 uppercase letters
      // e.g. $CURI...$SPOT gets captured with content starting "CURI short is..."
      if (/^[A-Z]{2,5}(?:\s|[^a-zA-Z]|$)/.test(trimmed) && !LATEX_CHAR_RE.test(trimmed))
        return match;

      return '`' + MATH_MARKER + trimmed + '`';
    },
  );

  // Step 6: Restore code blocks
  text = text.replace(
    new RegExp(`\\x00${CODE_MARKER}(\\d+)\\x00`, 'g'),
    (_, i: string) => codeBlocks[parseInt(i)],
  );

  // Step 7: Add plaintext language to code blocks without a language
  let inBlock = false;
  text = text
    .split('\n')
    .map((line) => {
      if (!inBlock && /^```(\w*)$/.exec(line)) {
        inBlock = true;
        return line === '```' ? '```plaintext' : line;
      } else if (inBlock && /^```$/.exec(line)) {
        inBlock = false;
      }
      return line;
    })
    .join('\n');

  const backticks = text.match(/```/g)?.length ?? 0;
  if (backticks !== 0 && backticks % 2 !== 0) {
    text = text + STREAMING_MARKER + '\n```';
  }
  return text;
};

export const Markdown = memo(
  ({
    source,
    style,
    maw,
    isGenerating,
    webSearchResults,
  }: {
    source: string;
    style?: CSSProperties;
    maw?: number;
    isGenerating?: boolean;
    webSearchResults?: { id?: string; title: string; source: string; content: string }[];
  }) => {
    const sourceCited = useMemo(() => {
      if (!webSearchResults?.length) return source;
      const footnotes = webSearchResults
        .map((c, i) => `[^${c.id ?? i + 1}]: ${c.source}`)
        .join('\n');
      return `${source}\n\n${footnotes}`;
    }, [source, webSearchResults]);

    return (
      <Typography style={{ overflowWrap: 'break-word', ...style }} maw={maw}>
        <ReactMarkdown
          skipHtml
          remarkPlugins={[RemarkGfm, RemarkBreaks]}
          rehypePlugins={isGenerating ? [rehypeStreamFade] : []}
          components={{
            ...components(webSearchResults),
            // Hide the footer section created by remark-gfm
            section: (props) => {
              if ('data-footnotes' in props) {
                return null;
              }
              return <section {...props} />;
            },
            footer: () => {
              // remark-gfm might wrap footnotes in a footer or section depending on version/config
              return null;
            },
          }}
        >
          {filter(sourceCited)}
        </ReactMarkdown>
      </Typography>
    );
  },
  (prev, next) =>
    prev.source === next.source &&
    prev.style === next.style &&
    prev.isGenerating === next.isGenerating &&
    prev.webSearchResults === next.webSearchResults, // Compare reference is enough for tool results
);

import { CSSProperties, Fragment, memo, useMemo } from 'react';
import { getTextFromChildren, takeStringOutOfNodeAndChildren } from '@/utils/text';
import { openExternal } from '@/utils/ui';
import ReactMarkdown, { Components } from 'react-markdown';
import {
  Blockquote,
  Group,
  ScrollArea,
  Text,
  ThemeIcon,
  Tooltip,
  Stack,
  Anchor,
  Pill,
  Typography,
} from '@mantine/core';
import RemarkGfm from 'remark-gfm';
import RemarkBreaks from 'remark-breaks';
import { CodeHighlight } from '@mantine/code-highlight';
import katex from 'katex';
import 'katex/dist/katex.min.css';
import { Icon } from '@iconify/react';
import { normalizeText } from '@tiny-chat/core-backend/src/types.ts';
import { visit, SKIP } from 'unist-util-visit';
import type { Plugin } from 'unified';
import type { Root, Element, Text as HastText } from 'hast';
import { SearchResult } from '@tiny-chat/core-backend/src/providers/search';

const rehypeStreamFade: Plugin<[], Root> = () => {
  return (tree) => {
    let totalLength = 0;
    visit(tree, 'text', (node: HastText) => {
      totalLength += node.value.length;
    });

    if (totalLength === 0) return;

    const animateChars = 15;
    const startIndex = Math.max(0, totalLength - animateChars);

    let currentIndex = 0;

    visit(tree, 'text', (node: HastText, index, parent) => {
      if (!parent || typeof index !== 'number') return;

      const nodeStart = currentIndex;
      const nodeLength = node.value.length;
      const nodeEnd = nodeStart + nodeLength;
      currentIndex += nodeLength;

      if (nodeEnd <= startIndex) return;

      const staticLength = Math.max(0, startIndex - nodeStart);
      const staticStr = node.value.slice(0, staticLength);
      const animatedStr = node.value.slice(staticLength);

      const newNodes: (HastText | Element)[] = [];
      if (staticStr) {
        newNodes.push({ type: 'text', value: staticStr });
      }

      for (let i = 0; i < animatedStr.length; i++) {
        const char = animatedStr[i];
        if (char.trim() === '') {
          const last = newNodes[newNodes.length - 1];
          if (last?.type === 'text') {
            last.value += char;
          } else {
            newNodes.push({ type: 'text', value: char });
          }
          continue;
        }

        const globalCharIndex = nodeStart + staticLength + i;
        newNodes.push({
          type: 'element',
          tagName: 'span',
          properties: {
            className: ['stream-char-fade'],
            key: `char-fade-${globalCharIndex}`,
          },
          children: [{ type: 'text', value: char }],
        });
      }

      parent.children.splice(index, 1, ...newNodes);
      return [SKIP, index + newNodes.length];
    });
  };
};

const STREAMING_MARKER = '\uE000';
const MATH_MARKER = '\uE001';
const CODE_MARKER = '\uE002';
const WRITING_MARKER = '\uE003';

const renderKatex = (math: string, displayMode: boolean): string | null => {
  try {
    return katex.renderToString(math, {
      displayMode,
      throwOnError: false,
      output: 'html',
    });
  } catch {
    return null;
  }
};

const components = (webSearchResults: SearchResult[] = []): Components => ({
  blockquote: (node) => {
    const text = getTextFromChildren(node.children);

    if (text.trim().startsWith(WRITING_MARKER)) {
      return (
        <Blockquote
          icon={
            <ThemeIcon variant="transparent" color="dimmed">
              <Icon icon="lucide:pencil-line" height={18} />
            </ThemeIcon>
          }
        >
          {takeStringOutOfNodeAndChildren(node.children, WRITING_MARKER)}
        </Blockquote>
      );
    }

    if (text.trim().startsWith('::>:: ')) {
      const lines = text.split('\n');
      let modelName = '';
      let contentLines = lines;

      const firstContent = lines[0].replace(/^::>::\s?/, '');
      if (firstContent.startsWith('::model=') && firstContent.endsWith('::')) {
        modelName = firstContent.slice('::model='.length, -2);
        contentLines = lines.slice(1);
      }

      return (
        <>
          {modelName && (
            <Group gap={5} c="dimmed" mb={4}>
              <Icon
                icon="lucide:message-square-quote"
                height={14}
                style={{ transform: 'scale(-1,1)' }}
              />
              <Text size="xs">{modelName}</Text>
            </Group>
          )}
          <Blockquote className="ignore-typography" mb="var(--mantine-spacing-lg)">
            {contentLines.map((line, index) => (
              <Fragment key={index}>
                {line.replace(/^::>::\s?/gm, '')}
                {index < contentLines.length - 1 && <br />}
              </Fragment>
            ))}
          </Blockquote>
        </>
      );
    }

    return <Blockquote>{node.children}</Blockquote>;
  },
  a: (props) => {
    if (webSearchResults && (props as { ['data-footnote-ref']?: string })['data-footnote-ref']) {
      const footnoteId = props.href?.replace('#user-content-fn-', '') ?? '';
      const citation = webSearchResults.find((c) => c.id === footnoteId);
      if (!citation) {
        // Fallback to index if no ID match (for older messages or if model ignored instructions)
        const index = parseInt(footnoteId, 10);
        const fallbackCitation = webSearchResults[index - 1];
        if (!fallbackCitation) return <sup>{props.children}</sup>;
        return (
          <Tooltip
            label={
              <Stack gap="xs" maw={300}>
                <Text size="sm" fw={500} lineClamp={2}>
                  {fallbackCitation.title}
                </Text>
                <Anchor size="xs" href={fallbackCitation.source} target="_blank" lineClamp={1}>
                  {fallbackCitation.source}
                </Anchor>
              </Stack>
            }
            multiline
            color="dark"
            position="bottom"
            bg="var(--tc-surface)"
            bd="1px solid var(--mantine-color-default-border)"
            p="md"
          >
            <Pill
              size="xs"
              style={{
                cursor: 'pointer',
                fontSize: '0.7em',
                margin: '0 2px',
                display: 'inline-flex',
              }}
              onClick={(e) => {
                e.preventDefault();
                void openExternal(fallbackCitation.source);
              }}
            >
              {fallbackCitation.title.length > 20
                ? fallbackCitation.title.slice(0, 17) + '…'
                : fallbackCitation.title}
            </Pill>
          </Tooltip>
        );
      }

      return (
        <Tooltip
          label={
            <Stack gap="xs" maw={300}>
              <Text size="sm" fw={500} lineClamp={2}>
                {citation.title}
              </Text>
              <Anchor size="xs" href={citation.source} target="_blank" lineClamp={1}>
                {citation.source}
              </Anchor>
            </Stack>
          }
          multiline
          color="dark"
          position="bottom"
          bg="var(--tc-surface)"
          bd="1px solid var(--mantine-color-default-border)"
          p="md"
        >
          <Pill
            size="xs"
            style={{
              cursor: 'pointer',
              fontSize: '0.7em',
              margin: '0 2px',
              display: 'inline-flex',
            }}
            onClick={(e) => {
              e.preventDefault();
              void openExternal(citation.source);
            }}
          >
            {citation.title.length > 20 ? citation.title.slice(0, 17) + '…' : citation.title}
          </Pill>
        </Tooltip>
      );
    }
    return (
      <a
        href={props.href}
        onClick={(e) => {
          if (!props.href) return;
          e.preventDefault();
          void openExternal(props.href);
        }}
      >
        {props.children}
      </a>
    );
  },
  code: (node) => {
    // eslint-disable-next-line @typescript-eslint/no-base-to-string
    const rawCode = String(node.children ?? '');

    // Display math — converted from $$...$$ by filter()
    if (node.className === 'language-math') {
      const html = renderKatex(rawCode.trim(), true);
      if (html) return <span className="math-display" dangerouslySetInnerHTML={{ __html: html }} />;
      return <pre>{rawCode}</pre>;
    }

    // Inline math — converted from $...$ by filter()
    if (!node.className && rawCode.startsWith(MATH_MARKER)) {
      const math = rawCode.slice(MATH_MARKER.length);
      const html = renderKatex(math, false);
      if (html) return <span className="math-inline" dangerouslySetInnerHTML={{ __html: html }} />;
      return <code>{math}</code>;
    }

    const isStreaming = rawCode.includes(STREAMING_MARKER);
    const code = (isStreaming ? rawCode.replace(STREAMING_MARKER, '') : rawCode).trimEnd();

    if (!node.className) {
      return <code>{code}</code>;
    }

    if (isStreaming) {
      return <pre style={{ padding: 25, maxHeight: 180, overflow: 'hidden' }}>{code}</pre>;
    }

    return (
      <div className="code-fade-in">
        <CodeHighlight
          code={code}
          language={node.className?.replace('language-', '')}
          withExpandButton={code.split('\n').length >= 8}
          defaultExpanded={code.split('\n').length < 8}
        />
      </div>
    );
  },
  table: (node) => {
    return (
      <ScrollArea scrollbars="x" type="always">
        <table>{node.children}</table>
      </ScrollArea>
    );
  },
});

const LATEX_CHAR_RE = /[\\^_{}]|\\[a-zA-Z]/;

const filter = (text: string) => {
  text = normalizeText(text);

  // Split combined citations like [^s1-2, s2-1] into separate ones like [^s1-2][^s2-1]
  text = text.replace(/\[\^([^\]]+)\]/g, (match, content: string) => {
    if (content.includes(',')) {
      return content
        .split(',')
        .map((c) => `[^${c.trim()}]`)
        .join('');
    }
    return match;
  });

  text = text.replace(/((?:^::>:: .*$\n?)+)/gm, (block) =>
    block.replace(/^::>:: (.*)$/gm, '> ::>:: $1'),
  );

  // Convert :::writing ... ::: directive blocks into standard blockquotes with the writing marker
  text = text.replace(/^:::writing\s*\n([\s\S]*?)^:::\s*$/gm, (_, content: string) => {
    const lines = content.trimEnd().split('\n');
    return lines.map((l: string, i: number) => `> ${i === 0 ? WRITING_MARKER : ''}${l}`).join('\n');
  });

  const codeBlocks: string[] = [];
  text = text.replace(/(`{3,}[\s\S]*?`{3,}|``[^`\n]*``|`[^`\n]+`)/g, (match) => {
    codeBlocks.push(match);
    return `\x00${CODE_MARKER}${codeBlocks.length - 1}\x00`;
  });

  // Step 2: Display math — $$...$$
  // Block form: $$ alone on line → fenced math block
  text = text.replace(
    /^[ \t]*\$\$([\s\S]*?)\$\$[ \t]*$/gm,
    (_, inner: string) => '```math\n' + inner.trim() + '\n```',
  );
  // Inline form: $$ with trailing content on same line → inline math marker
  text = text.replace(
    /\$\$((?:[^$]|\$(?!\$))+?)\$\$/g,
    (_, inner: string) => '`' + MATH_MARKER + inner.trim() + '`',
  );

  // Step 3: Display math — \[...\] (block, possibly multiline)
  text = text.replace(
    /^[ \t]*\\\[([\s\S]*?)\\][ \t]*$/gm,
    (_, inner: string) => '```math\n' + inner.trim() + '\n```',
  );

  // Step 4: Inline math — \(...\)
  // Allow any content that isn't a newline; filter false positives via LATEX_CHAR_RE
  text = text.replace(/\\\(([^\n]*?)\\\)/g, (match, inner: string) => {
    if (!LATEX_CHAR_RE.test(inner)) return match;
    return '`' + MATH_MARKER + inner.trim() + '`';
  });

  text = text.replace(
    /(?<![\\$a-zA-Z\d])\$[ \t]?((?:[^$\\\n]|\\.)+?)[ \t]?\$(?!\$)/g,
    (match, inner: string) => {
      const trimmed = inner.trim();
      if (!trimmed) return match;

      // Reject digit content with no LaTeX chars (e.g. $20k, $500)
      if (/^\d[\d,.]*[a-zA-Z]+$/.test(trimmed)) return match;

      // Reject ${ template literals
      if (trimmed.startsWith('{')) return match;

      // Reject if content starts with a ticker-like pattern: 2–5 uppercase letters
      // e.g. $CURI...$SPOT gets captured with content starting "CURI short is..."
      if (/^[A-Z]{2,5}(?:\s|[^a-zA-Z]|$)/.test(trimmed) && !LATEX_CHAR_RE.test(trimmed))
        return match;

      return '`' + MATH_MARKER + trimmed + '`';
    },
  );

  // Step 6: Restore code blocks
  text = text.replace(
    new RegExp(`\\x00${CODE_MARKER}(\\d+)\\x00`, 'g'),
    (_, i: string) => codeBlocks[parseInt(i)],
  );

  // Step 7: Add plaintext language to code blocks without a language
  let inBlock = false;
  text = text
    .split('\n')
    .map((line) => {
      if (!inBlock && /^```(\w*)$/.exec(line)) {
        inBlock = true;
        return line === '```' ? '```plaintext' : line;
      } else if (inBlock && /^```$/.exec(line)) {
        inBlock = false;
      }
      return line;
    })
    .join('\n');

  const backticks = text.match(/```/g)?.length ?? 0;
  if (backticks !== 0 && backticks % 2 !== 0) {
    text = text + STREAMING_MARKER + '\n```';
  }
  return text;
};

export const Markdown = memo(
  ({
    source,
    style,
    maw,
    isGenerating,
    webSearchResults,
  }: {
    source: string;
    style?: CSSProperties;
    maw?: number;
    isGenerating?: boolean;
    webSearchResults?: { id?: string; title: string; source: string; content: string }[];
  }) => {
    const sourceCited = useMemo(() => {
      if (!webSearchResults?.length) return source;
      const footnotes = webSearchResults
        .map((c, i) => `[^${c.id ?? i + 1}]: ${c.source}`)
        .join('\n');
      return `${source}\n\n${footnotes}`;
    }, [source, webSearchResults]);

    return (
      <Typography style={{ overflowWrap: 'break-word', ...style }} maw={maw}>
        <ReactMarkdown
          skipHtml
          remarkPlugins={[RemarkGfm, RemarkBreaks]}
          rehypePlugins={isGenerating ? [rehypeStreamFade] : []}
          components={{
            ...components(webSearchResults),
            // Hide the footer section created by remark-gfm
            section: (props) => {
              if ('data-footnotes' in props) {
                return null;
              }
              return <section {...props} />;
            },
            footer: () => {
              // remark-gfm might wrap footnotes in a footer or section depending on version/config
              return null;
            },
          }}
        >
          {filter(sourceCited)}
        </ReactMarkdown>
      </Typography>
    );
  },
  (prev, next) =>
    prev.source === next.source &&
    prev.style === next.style &&
    prev.isGenerating === next.isGenerating &&
    prev.webSearchResults === next.webSearchResults, // Compare reference is enough for tool results
);

import type { IncomingMessage, ServerResponse } from 'http';
import { auth, toHeaders, type User } from '../server.ts';
import type { zGenerateOutput } from '../types.ts';
import { getNextRunAt } from '../types.ts';
import {
  type ContextItem,
  type MessageUnomitted,
  normalizeText,
  texts,
  type zConfig,
  zData,
  type zDataPart,
  zGenerateInput,
} from '../types.ts';
import { chatProviders } from '../providers/chat/index.ts';
import { Author, type Chat } from '../../generated/prisma/client.ts';
import { tools } from '../tools/index.ts';
import { getMemoryContext, getQueryEmbedding } from '../routes/embeddings.ts';
import { format } from 'timeago.js';
import type { File } from '../../generated/prisma/client.ts';
import { searchFiles } from '../tools/file.ts';

export default async function generateHandler(req: IncomingMessage, res: ServerResponse) {
  try {
    const session = await auth.api.getSession({ headers: toHeaders(req.headers) });
    if (!session?.user) {
      res.writeHead(401);
      res.end('Unauthorized');
      return;
    }

    const body = await new Promise<string>((resolve, reject) => {
      let data = '';
      req.on('data', (chunk) => (data += chunk));
      req.on('end', () => resolve(data));
      req.on('error', reject);
    });
    const data = JSON.parse(body);
    const input = zGenerateInput.parse(data);

    const controller = new AbortController();
    res.on('close', () => controller.abort());

    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    const generation = generate(session.user, input, controller);
    for await (const event of generation) {
      res.write(`data: ${JSON.stringify(event)}\n\n`);
    }
  } catch (e: any) {
    console.trace('Error during generation:', e);
    res.write(`error: ${JSON.stringify({ stack: e.stack, message: e.message })}\n\n`);
  } finally {
    res.end();
  }
}

export async function* generate(
  user: User,
  input: zGenerateInput,
  controller: AbortController,
): AsyncGenerator<zGenerateOutput> {
  const provider = chatProviders.find((s) => s.name === input.config.provider);
  if (!provider) return;

  const baseContext: ContextItem[] = [];

  // Prefer persisted rows when IDs are present, then normalize mixed tool results into separate turns.
  const messageDatas = await globalThis.prisma.message.findMany({
    where: {
      id: {
        in: input.context.flatMap((m) => (m.id ? [m.id] : [])),
      },
    },
  });
  for (const item of input.context) {
    const messageData = messageDatas.find((m) => m.id === item.id);
    if (messageData) {
      baseContext.push(messageData as MessageUnomitted);
    } else {
      baseContext.push({ ...item, id: null });
    }
  }

  const chatId = baseContext.find((m): m is MessageUnomitted => !!m.id && !!m.chatId)?.chatId;
  const chat = chatId
    ? await globalThis.prisma.chat.findUniqueOrThrow({
        where: { id: chatId },
      })
    : undefined;

  const { context, instructions } = await buildGenerateInput(
    user,
    baseContext,
    await useConfigDefaults(user, input.config),
    input.overrideInstructions,
    chat,
  );

  // Agentic loop: keep generating until the model stops calling tools
  while (true) {
    const message = context[context.length - 1];

    console.log('Starting turn for message:', message);
    const stream = provider.generate(
      user,
      instructions,
      context,
      input.config,
      controller.signal,
      tools({ user, chat, message, messages: baseContext, generateInput: input }),
    );

    const modelMessage = { ...message, author: Author.MODEL, data: [] } as MessageUnomitted;
    const userMessage = { ...message, author: Author.USER, data: [] } as MessageUnomitted;

    try {
      for await (const event of stream) {
        yield event;

        if (event.type === 'data') {
          modelMessage.data.push(event.value);
        }

        if (event.type === 'special' && event.value.type === 'metadata') {
          modelMessage.metadata = event.value.value; // to push Gemini thoughtSignature into next pass
        }
      }
    } catch (e: any) {
      console.log('Error during generation:', e);
      throw e;
    }

    // Find any tool calls in this pass
    const toolCalls = modelMessage.data.filter((p) => p.type === 'toolCall');
    if (!toolCalls.length) break;

    // Execute each tool and collect results
    let needsUserInput = false;

    for (const part of toolCalls) {
      if (part.type !== 'toolCall') continue;

      const tool = tools({ user, chat, message, messages: baseContext, generateInput: input }).find(
        (t) => t.name === part.name,
      );
      if (!tool) {
        console.log(`Tool '${part.name}' does not exist`);
        userMessage.data.push({
          type: 'toolResult',
          id: part.id,
          name: part.name,
          error: true,
          value: `Tool "${part.name}" not found`,
        });
        continue;
      }

      if (tool.needsUserInput) {
        console.log(`Tool '${part.name}' requires user input, will end turn`);
        needsUserInput = true;
        continue; // TODO - user input should be requested during tool run
        // TODO - tool results should probably be collected?
      }

      try {
        const params = tool.schema.parse(part.args);
        console.log(`Tool '${part.name}' called, running with args:`, params);
        const value = await tool.run(
          { user, chat, message: message, messages: baseContext, generateInput: input },
          params,
        );
        userMessage.data.push({ type: 'toolResult', id: part.id, name: part.name, value });
      } catch (e: any) {
        console.warn(`Tool '${part.name}' threw an error:`, e);
        userMessage.data.push({
          type: 'toolResult',
          id: part.id,
          name: part.name,
          error: true,
          value: e.message ?? String(e),
        });
      }

      if (controller.signal.aborted) {
        console.warn('Aborting generation loop:', controller.signal.reason);
        break;
      }
    }

    // Emit the tool results to the client so the UI can display them
    for (const part of userMessage.data) {
      console.log(`Tool '${(part as Extract<zDataPart, { type: 'toolResult' }>).name}' succeeded`);
      yield { type: 'data', value: part };
    }

    if (needsUserInput) {
      console.log('Ending turn to wait for user input');
      controller.abort('Tool requires user input');
      break;
    }

    if (controller.signal.aborted) {
      console.warn('Aborting generation loop:', controller.signal.reason);
      break;
    }

    // Append the assistant turn and the tool results as a user turn, then loop
    context.push(modelMessage);
    context.push(userMessage);
  }
}

async function buildGenerateInput(
  user: User,
  messages: ContextItem[],
  config: zConfig,
  overrideInstructions?: string,
  chat?: Chat,
) {
  const memories = chat && !chat.incognito ? await getMemoryContext(user, messages) : [];

  const actions = chat
    ? await globalThis.prisma.action.findMany({
        where: { chatId: chat.id },
      })
    : [];

  console.log('Handling message with data:', messages[messages.length - 1]?.data);

  const context: ContextItem[] = await Promise.all(
    messages.map(async (m, i) => {
      let isFirstText = true;

      const uploadFiles: Record<string, File[]> = {};
      const uploadFileContexts: Record<string, string> = {};
      for (const upload of m.data.filter(
        (d): d is Extract<zDataPart, { type: 'upload' }> => d.type === 'upload',
      )) {
        uploadFiles[upload.id] = await globalThis.prisma.file.findMany({
          where: { uploadId: upload.id },
        });
        const query = await getQueryEmbedding(user, messages);
        if (query) {
          uploadFileContexts[upload.id] = await searchFiles(
            [m],
            query.query,
            query.queryEmbedding,
            -1,
            5,
          );
        }
      }

      return {
        ...m,
        data: m.data.flatMap((p): zDataPart[] => {
          if (p.type === 'upload') {
            console.log(
              `Handling upload '${p.name}' with ID ${p.id} and ${uploadFiles[p.id]?.length ?? 0} file(s)`,
            );
            if (uploadFiles[p.id]?.length === 1) {
              return [
                { type: 'text', value: `Uploaded file (${p.name}):` },
                {
                  type: 'inputFile',
                  name: uploadFiles[p.id][0].path[0],
                  mime: uploadFiles[p.id][0].mime,
                  data: Buffer.from(uploadFiles[p.id][0].data).toString('base64'),
                },
              ];
            } else if (uploadFiles[p.id]?.length) {
              const buildFileTreeMarkdown = (files: (typeof uploadFiles)[string]) => {
                const tree: Record<string, unknown> = {};

                for (const file of files) {
                  let node = tree;
                  for (let i = 0; i < file.path.length - 1; i++) {
                    const segment = file.path[i];
                    node[segment] ??= {};
                    node = node[segment] as Record<string, unknown>;
                  }
                  const filename = file.path[file.path.length - 1];
                  node[filename] = null; // leaf = file
                }

                const renderTree = (node: Record<string, unknown>, prefix = ''): string => {
                  const entries = Object.entries(node);
                  return entries
                    .map(([name, children], i) => {
                      const isLast = i === entries.length - 1;
                      const connector = isLast ? '└── ' : '├── ';
                      const childPrefix = prefix + (isLast ? '    ' : '│   ');
                      if (children === null) {
                        return `${prefix}${connector}${name}`;
                      }
                      const subtree = renderTree(children as Record<string, unknown>, childPrefix);
                      return `${prefix}${connector}${name}/\n${subtree}`;
                    })
                    .join('\n');
                };

                return '```\n' + renderTree(tree) + '\n```';
              };
              const treeMarkdown = buildFileTreeMarkdown(uploadFiles[p.id]);
              console.log(
                'File context:',
                uploadFileContexts[p.id]
                  .split('---')
                  .map((c) => c.trim().slice(0, 1000))
                  .join('\n\n---\n\n'),
              );
              return [
                {
                  type: 'text',
                  value: `Uploaded files (${p.name}):\n${treeMarkdown}\n\n---${uploadFileContexts[p.id]}`,
                },
              ];
            }
          }
          if (p.type === 'text') {
            let value = normalizeText(p.value).replace(/((?:^::>:: .*$\n?)+)/gm, (block) => {
              const lines = block
                .trim()
                .split('\n')
                .map((l) => l.replace(/^::>:: /, ''));
              let referencedModel = '';
              let contentLines = lines;
              if (lines[0].startsWith('::model=') && lines[0].endsWith('::')) {
                referencedModel = lines[0].slice('::model='.length, -2);
                contentLines = lines.slice(1);
              }
              const prefix = referencedModel ? `Earlier, ${referencedModel} said:\n` : '';
              return prefix + contentLines.map((l) => `> ${l}`).join('\n') + '\n';
            });
            if (isFirstText && m.id) {
              let heading;
              if (m.author === Author.USER) {
                heading = `[user]\n`;
                if (i !== 0) {
                  const previous = messages[i - 1];
                  if (previous.id) {
                    const delay = format(previous.createdAt, undefined, {
                      relativeDate: m.createdAt,
                    }).replace(' ago', '');
                    if (delay !== 'just now') {
                      heading += `[Conversation timing: ${delay} ${delay.endsWith('s') ? 'have' : 'has'} passed since the last message.]\n`;
                    }
                  }
                }
              } else {
                heading = `[assistant:model=${m.config.model}]\n`;
              }
              value = heading + '\n' + value;
              isFirstText = false;
            }
            return [{ ...p, value }];
          }
          return [p];
        }),
      };
    }),
  );

  context.splice(0, context.length, ...splitToolResults(context));

  // TODO - use XML? (multiline rrules, better model inference, etc)
  const userInstructions = chat && !chat.incognito ? user.settings.instructions : [];
  const defaultInstructions =
    `Formatting re-enabled.

## Instructions

Today's date is ${new Date().toLocaleDateString()}. For time-sensitive topics (news, software, etc.), search rather than relying on training data.
Always take conversation timing into account. Do not assume the chat is continuous. Consider whether the user's intent has changed between messages.

Render responses in Markdown — use headers, tables, lists, and code blocks where helpful. Use LaTeX for math. Keep paragraphs short.

When using the "search_web" tool, cite your sources using footnotes like [^s-n] (e.g., [^s4-1]), matching the "id" field of the search results found in the tool output.
Do NOT use simple [^1] indices; only use the explicit [^s-n] IDs provided in the results.
Do NOT repeat the list of sources at the end of your response; the system will display them automatically.

## Identity

This conversation may include responses from multiple AI models. Your model name is "${config.model}".
Only messages labeled [assistant:model=${config.model}] were written by you. Other assistant messages were written by different models that may have different knowledge and capabilities.
When referencing past assistant messages, always use the model name - do not say "I" if it wasn't "${config.model}". Critique past assistant messages from your own perspective when appropriate.

Critical: Do not include the [assistant:model=...] label in your response.

## Context

The user's scheduled actions in this chat:

${
  actions.length
    ? (
        await Promise.all(
          actions.flatMap(async (a) =>
            (await getNextRunAt(a))
              ? [`- [${a.id}] ${texts(zData.parse(a.data))} (${a.schedule})`]
              : [],
          ),
        )
      ).join('\n')
    : '- (none)'
}

Relevant memories of the user across all chats:

${memories.length ? memories.map((m) => `- ${m}`).join('\n') : '- (none)'}

## Actions

Actions allow for prompts to be sent automatically on a recurring schedule.
If the user asks for regular updates on a topic, use the add_action tool to create an action for it.
If regular updates would be useful for a topic, but the user hasn't asked yet, ask proactively if they'd like an action created.

## Memories

When the user shares information that could improve future chats, store it as memory even if it was mentioned only once.
Save anything that could be useful in the future, even if it's not obvious now. When unsure, prefer storing the memory with an appropriate confidence score rather than skipping it entirely.
When discussing code, pay special attention to the user's tech stack, environment, architectural decisions, and pain points.
SHORT_TERM and MEDIUM_TERM memories are encouraged for active conversations, experiments, or temporary workflows.
Use search_memory to find more when it could improve the response.` +
    (userInstructions?.length
      ? `

## User

The user provided the following instructions:

${userInstructions.join('\n')}`
      : '');

  console.log(
    'Built context:',
    context
      .filter((m) => m.data.some((d) => d.type === 'text' && d.value.trim() !== ''))
      .map(
        (m) =>
          `<${m.author}> ${texts(m.data)
            .replace(/\[[^\]\n]+]/g, '')
            .replace('\n', ' ')
            .slice(0, 100)}`,
      )
      .join('\n'),
    'And instructions:',
    overrideInstructions ?? defaultInstructions,
  );

  return { context, instructions: overrideInstructions ?? defaultInstructions };
}

export function splitToolResults(context: ContextItem[]) {
  const messages: ContextItem[] = [];
  for (const original of context) {
    const parts = zData.parse(original.data);
    const message = { ...original, data: [] } as MessageUnomitted;

    for (const part of parts) {
      const isCurrentToolResult = part.type === 'toolResult';
      const hasToolResult = message.data.some((p) => p.type === 'toolResult');
      const hasNonToolResult = message.data.some((p) => p.type !== 'toolResult');

      // If transitioning between toolResult and non-toolResult blocks, push and reset
      if ((isCurrentToolResult && hasNonToolResult) || (!isCurrentToolResult && hasToolResult)) {
        messages.push({ ...message });
        message.data = [];
      }

      message.data.push(part);

      // Correctly assign the author for the current block
      if (isCurrentToolResult) {
        message.author = Author.USER;
      } else if (part.type === 'toolCall') {
        message.author = Author.MODEL;
      } else {
        message.author = original.author;
      }
    }
    if (message.data.length) messages.push(message);
  }
  return messages;
}

export async function useConfigDefaults(user: User, config: zConfig) {
  const provider = chatProviders.find((s) => s.name === config.provider);
  if (!provider) throw new Error(`Provider ${config.provider} not found`);
  const args = (await provider.getModels(user)).find((m) => m.name === config.model)?.args ?? [];
  console.log('Model args:', args);
  const inputArgs = (config.args ?? {}) as Record<string, unknown>;
  for (const arg of args) {
    if (inputArgs?.[arg.name] === undefined) {
      console.log(`Using default value for arg ${arg.name}:`, arg.default);
      if (config.args === undefined) config.args = {};
      inputArgs[arg.name] = arg.default;
    }
  }
  config.args = inputArgs;
  return config;
}

import type { IncomingMessage, ServerResponse } from 'http';
import { auth, toHeaders, type User } from '../server.ts';
import type { zGenerateOutput } from '../types.ts';
import { getNextRunAt } from '../types.ts';
import {
  type ContextItem,
  type MessageUnomitted,
  normalizeText,
  texts,
  type zConfig,
  zData,
  type zDataPart,
  zGenerateInput,
} from '../types.ts';
import { chatProviders } from '../providers/chat/index.ts';
import { Author, type Chat } from '../../generated/prisma/client.ts';
import { tools } from '../tools/index.ts';
import { getMemoryContext, getQueryEmbedding } from '../routes/embeddings.ts';
import { format } from 'timeago.js';
import type { File } from '../../generated/prisma/client.ts';
import { searchFiles } from '../tools/file.ts';

export default async function generateHandler(req: IncomingMessage, res: ServerResponse) {
  try {
    const session = await auth.api.getSession({ headers: toHeaders(req.headers) });
    if (!session?.user) {
      res.writeHead(401);
      res.end('Unauthorized');
      return;
    }

    const body = await new Promise<string>((resolve, reject) => {
      let data = '';
      req.on('data', (chunk) => (data += chunk));
      req.on('end', () => resolve(data));
      req.on('error', reject);
    });
    const data = JSON.parse(body);
    const input = zGenerateInput.parse(data);

    const controller = new AbortController();
    res.on('close', () => controller.abort());

    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    const generation = generate(session.user, input, controller);
    for await (const event of generation) {
      res.write(`data: ${JSON.stringify(event)}\n\n`);
    }
  } catch (e: any) {
    console.trace('Error during generation:', e);
    res.write(`error: ${JSON.stringify({ stack: e.stack, message: e.message })}\n\n`);
  } finally {
    res.end();
  }
}

export async function* generate(
  user: User,
  input: zGenerateInput,
  controller: AbortController,
): AsyncGenerator<zGenerateOutput> {
  const provider = chatProviders.find((s) => s.name === input.config.provider);
  if (!provider) return;

  const baseContext: ContextItem[] = [];

  // Prefer persisted rows when IDs are present, then normalize mixed tool results into separate turns.
  const messageDatas = await globalThis.prisma.message.findMany({
    where: {
      id: {
        in: input.context.flatMap((m) => (m.id ? [m.id] : [])),
      },
    },
  });
  for (const item of input.context) {
    const messageData = messageDatas.find((m) => m.id === item.id);
    if (messageData) {
      baseContext.push(messageData as MessageUnomitted);
    } else {
      baseContext.push({ ...item, id: null });
    }
  }

  const chatId = baseContext.find((m): m is MessageUnomitted => !!m.id && !!m.chatId)?.chatId;
  const chat = chatId
    ? await globalThis.prisma.chat.findUniqueOrThrow({
        where: { id: chatId },
      })
    : undefined;

  const { context, instructions } = await buildGenerateInput(
    user,
    baseContext,
    await useConfigDefaults(user, input.config),
    input.overrideInstructions,
    chat,
  );

  // Agentic loop: keep generating until the model stops calling tools
  const allToolResults: Extract<zDataPart, { type: 'toolResult' }>[] = [];
  while (true) {
    const message = context[context.length - 1];

    console.log('Starting turn for message:', message);
    const stream = provider.generate(
      user,
      instructions,
      context,
      input.config,
      controller.signal,
      tools({
        user,
        chat,
        message,
        messages: baseContext,
        generateInput: input,
        allToolResults,
      }),
    );

    const modelMessage = { ...message, author: Author.MODEL, data: [] } as MessageUnomitted;
    const userMessage = { ...message, author: Author.USER, data: [] } as MessageUnomitted;

    try {
      for await (const event of stream) {
        yield event;

        if (event.type === 'data') {
          modelMessage.data.push(event.value);
        }

        if (event.type === 'special' && event.value.type === 'metadata') {
          modelMessage.metadata = event.value.value; // to push Gemini thoughtSignature into next pass
        }
      }
    } catch (e: any) {
      console.log('Error during generation:', e);
      throw e;
    }

    // Find any tool calls in this pass
    const toolCalls = modelMessage.data.filter((p) => p.type === 'toolCall');
    if (!toolCalls.length) break;

    // Execute each tool and collect results
    let needsUserInput = false;

    for (const part of toolCalls) {
      if (part.type !== 'toolCall') continue;

      const tool = tools({
        user,
        chat,
        message,
        messages: baseContext,
        generateInput: input,
        allToolResults,
      }).find((t) => t.name === part.name);
      if (!tool) {
        console.log(`Tool '${part.name}' does not exist`);
        userMessage.data.push({
          type: 'toolResult',
          id: part.id,
          name: part.name,
          error: true,
          value: `Tool "${part.name}" not found`,
        });
        continue;
      }

      if (tool.needsUserInput) {
        console.log(`Tool '${part.name}' requires user input, will end turn`);
        needsUserInput = true;
        continue; // TODO - user input should be requested during tool run
        // TODO - tool results should probably be collected?
      }

      try {
        const params = tool.schema.parse(part.args);
        console.log(`Tool '${part.name}' called, running with args:`, params);
        const value = await tool.run(
          {
            user,
            chat,
            message: message,
            messages: baseContext,
            generateInput: input,
            allToolResults,
          },
          params,
        );
        const result: Extract<zDataPart, { type: 'toolResult' }> = {
          type: 'toolResult',
          id: part.id,
          name: part.name,
          value,
        };
        userMessage.data.push(result);
        allToolResults.push(result);
      } catch (e: any) {
        console.warn(`Tool '${part.name}' threw an error:`, e);
        userMessage.data.push({
          type: 'toolResult',
          id: part.id,
          name: part.name,
          error: true,
          value: e.message ?? String(e),
        });
      }

      if (controller.signal.aborted) {
        console.warn('Aborting generation loop:', controller.signal.reason);
        break;
      }
    }

    // Emit the tool results to the client so the UI can display them
    for (const part of userMessage.data) {
      console.log(`Tool '${(part as Extract<zDataPart, { type: 'toolResult' }>).name}' succeeded`);
      yield { type: 'data', value: part };
    }

    if (needsUserInput) {
      console.log('Ending turn to wait for user input');
      controller.abort('Tool requires user input');
      break;
    }

    if (controller.signal.aborted) {
      console.warn('Aborting generation loop:', controller.signal.reason);
      break;
    }

    // Append the assistant turn and the tool results as a user turn, then loop
    context.push(modelMessage);
    context.push(userMessage);
  }
}

async function buildGenerateInput(
  user: User,
  messages: ContextItem[],
  config: zConfig,
  overrideInstructions?: string,
  chat?: Chat,
) {
  const memories = chat && !chat.incognito ? await getMemoryContext(user, messages) : [];

  const actions = chat
    ? await globalThis.prisma.action.findMany({
        where: { chatId: chat.id },
      })
    : [];

  console.log('Handling message with data:', messages[messages.length - 1]?.data);

  const context: ContextItem[] = await Promise.all(
    messages.map(async (m, i) => {
      let isFirstText = true;

      const uploadFiles: Record<string, File[]> = {};
      const uploadFileContexts: Record<string, string> = {};
      for (const upload of m.data.filter(
        (d): d is Extract<zDataPart, { type: 'upload' }> => d.type === 'upload',
      )) {
        uploadFiles[upload.id] = await globalThis.prisma.file.findMany({
          where: { uploadId: upload.id },
        });
        const query = await getQueryEmbedding(user, messages);
        if (query) {
          uploadFileContexts[upload.id] = await searchFiles(
            [m],
            query.query,
            query.queryEmbedding,
            -1,
            5,
          );
        }
      }

      return {
        ...m,
        data: m.data.flatMap((p): zDataPart[] => {
          if (p.type === 'upload') {
            console.log(
              `Handling upload '${p.name}' with ID ${p.id} and ${uploadFiles[p.id]?.length ?? 0} file(s)`,
            );
            if (uploadFiles[p.id]?.length === 1) {
              return [
                { type: 'text', value: `Uploaded file (${p.name}):` },
                {
                  type: 'inputFile',
                  name: uploadFiles[p.id][0].path[0],
                  mime: uploadFiles[p.id][0].mime,
                  data: Buffer.from(uploadFiles[p.id][0].data).toString('base64'),
                },
              ];
            } else if (uploadFiles[p.id]?.length) {
              const buildFileTreeMarkdown = (files: (typeof uploadFiles)[string]) => {
                const tree: Record<string, unknown> = {};

                for (const file of files) {
                  let node = tree;
                  for (let i = 0; i < file.path.length - 1; i++) {
                    const segment = file.path[i];
                    node[segment] ??= {};
                    node = node[segment] as Record<string, unknown>;
                  }
                  const filename = file.path[file.path.length - 1];
                  node[filename] = null; // leaf = file
                }

                const renderTree = (node: Record<string, unknown>, prefix = ''): string => {
                  const entries = Object.entries(node);
                  return entries
                    .map(([name, children], i) => {
                      const isLast = i === entries.length - 1;
                      const connector = isLast ? '└── ' : '├── ';
                      const childPrefix = prefix + (isLast ? '    ' : '│   ');
                      if (children === null) {
                        return `${prefix}${connector}${name}`;
                      }
                      const subtree = renderTree(children as Record<string, unknown>, childPrefix);
                      return `${prefix}${connector}${name}/\n${subtree}`;
                    })
                    .join('\n');
                };

                return '```\n' + renderTree(tree) + '\n```';
              };
              const treeMarkdown = buildFileTreeMarkdown(uploadFiles[p.id]);
              console.log(
                'File context:',
                uploadFileContexts[p.id]
                  .split('---')
                  .map((c) => c.trim().slice(0, 1000))
                  .join('\n\n---\n\n'),
              );
              return [
                {
                  type: 'text',
                  value: `Uploaded files (${p.name}):\n${treeMarkdown}\n\n---${uploadFileContexts[p.id]}`,
                },
              ];
            }
          }
          if (p.type === 'text') {
            let value = normalizeText(p.value).replace(/((?:^::>:: .*$\n?)+)/gm, (block) => {
              const lines = block
                .trim()
                .split('\n')
                .map((l) => l.replace(/^::>:: /, ''));
              let referencedModel = '';
              let contentLines = lines;
              if (lines[0].startsWith('::model=') && lines[0].endsWith('::')) {
                referencedModel = lines[0].slice('::model='.length, -2);
                contentLines = lines.slice(1);
              }
              const prefix = referencedModel ? `Earlier, ${referencedModel} said:\n` : '';
              return prefix + contentLines.map((l) => `> ${l}`).join('\n') + '\n';
            });
            if (isFirstText && m.id) {
              let heading;
              if (m.author === Author.USER) {
                heading = `[user]\n`;
                if (i !== 0) {
                  const previous = messages[i - 1];
                  if (previous.id) {
                    const delay = format(previous.createdAt, undefined, {
                      relativeDate: m.createdAt,
                    }).replace(' ago', '');
                    if (delay !== 'just now') {
                      heading += `[Conversation timing: ${delay} ${delay.endsWith('s') ? 'have' : 'has'} passed since the last message.]\n`;
                    }
                  }
                }
              } else {
                heading = `[assistant:model=${m.config.model}]\n`;
              }
              value = heading + '\n' + value;
              isFirstText = false;
            }
            return [{ ...p, value }];
          }
          return [p];
        }),
      };
    }),
  );

  context.splice(0, context.length, ...splitToolResults(context));

  // TODO - use XML? (multiline rrules, better model inference, etc)
  const userInstructions = chat && !chat.incognito ? user.settings.instructions : [];
  const defaultInstructions =
    `Formatting re-enabled.

## Instructions

Today's date is ${new Date().toLocaleDateString()}. For time-sensitive topics (news, software, etc.), search rather than relying on training data.
Always take conversation timing into account. Do not assume the chat is continuous. Consider whether the user's intent has changed between messages.

Render responses in Markdown — use headers, tables, lists, and code blocks where helpful. Use LaTeX for math. Keep paragraphs short.

When using the "search_web" tool, cite your sources using footnotes like [^s-n] (e.g., [^s4-1]), matching the "id" field of the search results found in the tool output.
Do NOT use simple [^1] indices; only use the explicit [^s-n] IDs provided in the results.
Do NOT repeat the list of sources at the end of your response; the system will display them automatically.

## Identity

This conversation may include responses from multiple AI models. Your model name is "${config.model}".
Only messages labeled [assistant:model=${config.model}] were written by you. Other assistant messages were written by different models that may have different knowledge and capabilities.
When referencing past assistant messages, always use the model name - do not say "I" if it wasn't "${config.model}". Critique past assistant messages from your own perspective when appropriate.

Critical: Do not include the [assistant:model=...] label in your response.

## Context

The user's scheduled actions in this chat:

${
  actions.length
    ? (
        await Promise.all(
          actions.flatMap(async (a) =>
            (await getNextRunAt(a))
              ? [`- [${a.id}] ${texts(zData.parse(a.data))} (${a.schedule})`]
              : [],
          ),
        )
      ).join('\n')
    : '- (none)'
}

Relevant memories of the user across all chats:

${memories.length ? memories.map((m) => `- ${m}`).join('\n') : '- (none)'}

## Actions

Actions allow for prompts to be sent automatically on a recurring schedule.
If the user asks for regular updates on a topic, use the add_action tool to create an action for it.
If regular updates would be useful for a topic, but the user hasn't asked yet, ask proactively if they'd like an action created.

## Memories

When the user shares information that could improve future chats, store it as memory even if it was mentioned only once.
Save anything that could be useful in the future, even if it's not obvious now. When unsure, prefer storing the memory with an appropriate confidence score rather than skipping it entirely.
When discussing code, pay special attention to the user's tech stack, environment, architectural decisions, and pain points.
SHORT_TERM and MEDIUM_TERM memories are encouraged for active conversations, experiments, or temporary workflows.
Use search_memory to find more when it could improve the response.` +
    (userInstructions?.length
      ? `

## User

The user provided the following instructions:

${userInstructions.join('\n')}`
      : '');

  console.log(
    'Built context:',
    context
      .filter((m) => m.data.some((d) => d.type === 'text' && d.value.trim() !== ''))
      .map(
        (m) =>
          `<${m.author}> ${texts(m.data)
            .replace(/\[[^\]\n]+]/g, '')
            .replace('\n', ' ')
            .slice(0, 100)}`,
      )
      .join('\n'),
    'And instructions:',
    overrideInstructions ?? defaultInstructions,
  );

  return { context, instructions: overrideInstructions ?? defaultInstructions };
}

export function splitToolResults(context: ContextItem[]) {
  const messages: ContextItem[] = [];
  for (const original of context) {
    const parts = zData.parse(original.data);
    const message = { ...original, data: [] } as MessageUnomitted;

    for (const part of parts) {
      const isCurrentToolResult = part.type === 'toolResult';
      const hasToolResult = message.data.some((p) => p.type === 'toolResult');
      const hasNonToolResult = message.data.some((p) => p.type !== 'toolResult');

      // If transitioning between toolResult and non-toolResult blocks, push and reset
      if ((isCurrentToolResult && hasNonToolResult) || (!isCurrentToolResult && hasToolResult)) {
        messages.push({ ...message });
        message.data = [];
      }

      message.data.push(part);

      // Correctly assign the author for the current block
      if (isCurrentToolResult) {
        message.author = Author.USER;
      } else if (part.type === 'toolCall') {
        message.author = Author.MODEL;
      } else {
        message.author = original.author;
      }
    }
    if (message.data.length) messages.push(message);
  }
  return messages;
}

export async function useConfigDefaults(user: User, config: zConfig) {
  const provider = chatProviders.find((s) => s.name === config.provider);
  if (!provider) throw new Error(`Provider ${config.provider} not found`);
  const args = (await provider.getModels(user)).find((m) => m.name === config.model)?.args ?? [];
  console.log('Model args:', args);
  const inputArgs = (config.args ?? {}) as Record<string, unknown>;
  for (const arg of args) {
    if (inputArgs?.[arg.name] === undefined) {
      console.log(`Using default value for arg ${arg.name}:`, arg.default);
      if (config.args === undefined) config.args = {};
      inputArgs[arg.name] = arg.default;
    }
  }
  config.args = inputArgs;
  return config;
}
